  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Couteaux-(Roublard).html&quot; title=&quot;Ma&#238;tre des couteaux&quot;&gt;Ma&#238;tre des couteaux&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-&#201;p&#233;es-(Roublard).html&quot; title=&quot;Ma&#238;tre des &#233;p&#233;es&quot;&gt;Ma&#238;tre des &#233;p&#233;es&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Tengu-(Race).html&quot; title=&quot;Les tengus&quot;&gt;Tengu&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Du-D&#233;guisement-(Roublard).html&quot; title=&quot;Ma&#238;tre du d&#233;guisement&quot;&gt;Ma&#238;tre du d&#233;guisement&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;dium-Factice-(Roublard).html&quot; title=&quot;M&#233;dium factice&quot;&gt;M&#233;dium factice&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pilleur-Occulte-(Roublard).html&quot; title=&quot;Pilleur occulte&quot;&gt;Pilleur occulte&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aquatique-(Race).html&quot; title=&quot;Les aquatiques&quot;&gt;Aquatique&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pirate-(Roublard).html&quot; title=&quot;Pirate&quot;&gt;Pirate&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Roi-De-L&#233;vasion-(Roublard).html&quot; title=&quot;Roi de l&amp;#39;&#233;vasion&quot;&gt;Roi de l&#39;&#233;vasion&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Roublard-Sanctifi&#233;-(Roublard).html&quot; title=&quot;Roublard sanctifi&#233;&quot;&gt;Roublard sanctifi&#233;&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tireur-Embusqu&#233;-(Roublard).html&quot; title=&quot;Tireur embusqu&#233;&quot;&gt;Tireur embusqu&#233;&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Voleur-Fant&#244;me-(Roublard).html&quot; title=&quot;Voleur fant&#244;me&quot;&gt;Voleur fant&#244;me&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Voyou-(Roublard).html&quot; title=&quot;Voyou&quot;&gt;Voyou&lt;/a&gt; (MJRA)&lt;/li&gt;&lt;br /&gt;&lt;br /&gt;  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ninja.html&quot; title=&quot;Le ninja&quot;&gt;Le ninja&lt;/a&gt; (classe alternative) (AG)&lt;/li&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de lintrigue (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Intrigue/Art de l&#39;intrigue&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUI.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;&#201;galement connus sous le nom de gentleman voleur ou de dame voleuse, les voleurs fant&#244;mes ne connaissent pas le d&#233;sespoir d&#39;une vie difficile comme beaucoup de roublards. Au contraire, ils sont issus des rangs de l&#39;&#233;lite, se sont lass&#233;s de leur parure et recherchent des sensations fortes dans des actes criminels, audacieux et complexes. Les voleurs fant&#244;mes n&#39;ont pas besoin d&#39;argent, alors ils accomplissent souvent des actes tels que s&#39;introduire dans un coffre-fort s&#233;curis&#233; pour sentir l&#39;adr&#233;naline monter, pr&#233;f&#233;rant laisser une carte de visite plut&#244;t que de cambrioler l&#39;endroit.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;&#201;ducation raffin&#233;e (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;&#201;ducation_raffin&#233;e_Ext_0&quot; href=&quot;#&#201;ducation_raffin&#233;e_Ext_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un voleur fant&#244;me ajoute &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;quitation.html&quot; title=&quot;&#201;quitation&quot;&gt;&#201;quitation&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;Premiers secours&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; et toutes les comp&#233;tences de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; &#224; sa liste de comp&#233;tences de classe. De plus, il choisit une de ses comp&#233;tences de classe de roublard et ajoute la moiti&#233; de son niveau de roublard &#224; tous les tests de &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html&quot; title=&quot;Les comp&#233;tences&quot;&gt;comp&#233;tence&lt;/a&gt; utilisant celle-ci. Au niveau 3 et tous les 2 niveaux de roublard par la suite, il choisit une comp&#233;tence de classe de roublard suppl&#233;mentaire et ajoute &#233;galement la moiti&#233; de son niveau de roublard &#224; tous les tests de comp&#233;tence utilisant celle-ci. &#192; partir du niveau 4, si le voleur fant&#244;me est un &lt;a class=&quot;pagelink&quot; href=&quot;Roublard-Unchained.html&quot; title=&quot;Le roublard unchained&quot;&gt;roublard unchained&lt;/a&gt;, il gagne les &lt;a class=&quot;pagelink&quot; href=&quot;Extensions-De-Comp&#233;tences.html&quot; title=&quot;Extensions de comp&#233;tences&quot;&gt;extensions de comp&#233;tences&lt;/a&gt; de chacune de ces comp&#233;tences gr&#226;ce &#224; sa &lt;a class=&quot;pagelink&quot; href=&quot;Roublard-Unchained.html#SPECIALITEDUROUBLARD&quot; title=&quot;Le roublard unchained&quot;&gt;sp&#233;cialit&#233; du roublard&lt;/a&gt; au lieu de choisir une comp&#233;tence tous les 5 niveaux, et il ajoute la moiti&#233; de son niveau de roublard &#224; son nombre de rangs pour d&#233;terminer s&#39;il re&#231;oit une extension de comp&#233;tence (ainsi, un voleur fant&#244;me de niveau 7 avec 7 rangs dans une comp&#233;tence choisie comptera comme ayant 10 rangs et recevra la deuxi&#232;me extension de comp&#233;tence).&lt;br /&gt;&lt;br /&gt;Cette capacit&#233; modifie les comp&#233;tences de classe du roublard et remplace &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#ATTAQUESOURNOISE&quot; title=&quot;Le roublard&quot;&gt;attaque sournoise&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#RECHERCHEDESPIEGES&quot; title=&quot;Le roublard&quot;&gt;recherche des pi&#232;ges&lt;/a&gt;. Pour un &lt;a class=&quot;pagelink&quot; href=&quot;Roublard-Unchained.html&quot; title=&quot;Le roublard unchained&quot;&gt;roublard unchained&lt;/a&gt;, elle modifie &#233;galement &lt;a class=&quot;pagelink&quot; href=&quot;Roublard-Unchained.html#SPECIALITEDUROUBLARD&quot; title=&quot;Le roublard unchained&quot;&gt;sp&#233;cialit&#233; du roublard&lt;/a&gt; et remplace &lt;a class=&quot;pagelink&quot; href=&quot;Roublard-Unchained.html#BLESSUREINCAPACITANTE&quot; title=&quot;Le roublard unchained&quot;&gt;blessure d&#233;bilitante&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;&#201;ducation &#233;tendue (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;&#201;ducation_&#233;tendue_Ext_1&quot; href=&quot;#&#201;ducation_&#233;tendue_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;div style=&quot;float:right; padding-left: 6px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;&lt;u&gt;Ce texte a &#233;t&#233; modifi&#233; suite &#224; la FAQ suivante :&lt;/u&gt;&lt;br /&gt;&lt;br /&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Lart-De-Lintrigue.html#10&quot; title=&quot;FAQ- de l&amp;#39;Art de l&amp;#39;intrigue&quot;&gt;→&lt;/a&gt; Voleur fant&#244;me : Le niveau de roublard du voleur fant&#244;me compte-t-il comme son niveau de justicier afin de remplir les conditions des talents sociaux ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Oui.  &lt;i&gt;(Retour &#224; l&#39;&lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Voleur-Fant&#244;me-(Roublard).html&quot; title=&quot;Voleur fant&#244;me&quot;&gt;arch&#233;type&lt;/a&gt;&lt;/u&gt;)&lt;/i&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:50px; cursor:pointer&quot; src=&quot;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&quot; title=&quot;Cliquez pour afficher/cacher une FAQ officielle relative &#224; ce texte&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqalt1.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&#39;;&quot; /&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;Les &#233;tudes approfondies d&#39;un voleur fant&#244;me avec des tuteurs co&#251;teux lui permettent de rester &#224; jour dans ses connaissances martiales et magiques, ainsi que dans ses comp&#233;tences. Il peut choisir les talents de roublard &lt;a class=&quot;pagelink&quot; href=&quot;Talents.html#BOTTESECRETE&quot; title=&quot;Les talents de roublard&quot;&gt;botte secr&#232;te&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Talents.html#MAGIEMINEURE&quot; title=&quot;Les talents de roublard&quot;&gt;magie mineure&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Talents.html#MAGIEMAJEURE&quot; title=&quot;Les talents de roublard&quot;&gt;magie majeure&lt;/a&gt; autant de fois qu&#39;il le souhaite, et peut choisir le don &lt;a class=&quot;pagelink&quot; href=&quot;Talent.html&quot; title=&quot;Talent&quot;&gt;Talent&lt;/a&gt; &#224; la place d&#39;un talent de roublard, &#233;galement autant de fois qu&#39;il le souhaite. Enfin, il peut choisir un &lt;a class=&quot;pagelink&quot; href=&quot;Talents-Sociaux.html&quot; title=&quot;Les talents sociaux du justicier&quot;&gt;talent social&lt;/a&gt; de justicier &#224; la place d&#39;un &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#TALENTDEROUBLARD&quot; title=&quot;Le roublard&quot;&gt;talent de roublard&lt;/a&gt;, &#224; l&#39;exception de &lt;a class=&quot;pagelink&quot; href=&quot;Talents-Sociaux.html#GRACESOCIALE&quot; title=&quot;Les talents sociaux du justicier&quot;&gt;gr&#226;ce sociale&lt;/a&gt; et des talents sociaux de justicier qui n&#233;cessitent d&#39;&#234;tre un artisan ou un professionnel. Pour ce qui est des talents sociaux de justicier, un voleur fant&#244;me n&#39;a pas d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Justicier.html#DOUBLEIDENTIT&#201;&quot; title=&quot;Le justicier&quot;&gt;identit&#233; justici&#232;re&lt;/a&gt; et est toujours consid&#233;r&#233; comme &#233;tant dans son &lt;a class=&quot;pagelink&quot; href=&quot;Justicier.html#DOUBLEIDENTIT&#201;&quot; title=&quot;Le justicier&quot;&gt;identit&#233; sociale&lt;/a&gt;. Un voleur fant&#244;me utilise son niveau de roublard comme niveau de justicier pour s&#39;avoir s&#39;il remplit les conditions de ces talents sociaux. Cette capacit&#233; modifie &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#TALENTDEROUBLARD&quot; title=&quot;Le roublard&quot;&gt;talent de roublard&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Perception sociale (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Perception_sociale_Ext_2&quot; href=&quot;#Perception_sociale_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 3, le sixi&#232;me sens social d&#39;un voleur fant&#244;me lui permet d&#39;&#233;viter le danger dans les situations sociales et d&#39;agir en premier lorsqu&#39;il &#233;clate. Il b&#233;n&#233;ficie d&#39;un bonus de +1 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; pour &#233;viter d&#39;&#234;tre surpris par un ennemi, aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt; pour surprendre un ennemi, et aux tests d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;roulement-Dun-Combat#Initiative.html&quot; title=&quot;initiative&quot;&gt;initiative&lt;/a&gt; lors des &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;roulement-Dun-Combat#Roundsurprise.html&quot; title=&quot;round de surprise&quot;&gt;rounds de surprise&lt;/a&gt; qui ont n&#233;cessit&#233; des tests de Bluff et de &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; pour d&#233;terminer la surprise. Ce bonus augmente de 1 au niveau 3 et tous les 3 niveaux de roublard par la suite. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#SENSDESPIEGES&quot; title=&quot;Le roublard&quot;&gt;sens des pi&#232;ges&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Ma&#238;tre de tout (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Ma&#238;tre_de_tout_Ext_3&quot; href=&quot;#Ma&#238;tre_de_tout_Ext_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 20, un voleur fant&#244;me peut relancer n&#39;importe quel test de comp&#233;tence, &#224; condition qu&#39;il s&#39;agisse d&#39;une comp&#233;tence de classe dans laquelle il est form&#233;. Il doit conserver le second r&#233;sultat, m&#234;me s&#39;il est moins bon. Il ne peut pas utiliser cette capacit&#233; plus d&#39;une fois par minute. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#COUPDEMAITRE&quot; title=&quot;Le roublard&quot;&gt;coup de ma&#238;tre&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Talents de roublard&lt;a class=&quot;headeranchor&quot; id=&quot;Talents_de_roublard_4&quot; href=&quot;#Talents_de_roublard_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Ces talents de roublard viennent compl&#233;ter l&#39;arch&#233;type de voleur fant&#244;me : &lt;a class=&quot;pagelink&quot; href=&quot;Talents.html#BOTTESECRETE&quot; title=&quot;Les talents de roublard&quot;&gt;botte secr&#232;te&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Talents.html#MAGIEMAJEURE&quot; title=&quot;Les talents de roublard&quot;&gt;magie majeure&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Talents.html#MAGIEMINEURE&quot; title=&quot;Les talents de roublard&quot;&gt;magie mineure&lt;/a&gt; (ainsi que &lt;a class=&quot;pagelink&quot; href=&quot;Talents-Unchained.html#CERTITUDE&quot; title=&quot;Les talents du roublard unchained&quot;&gt;certitude&lt;/a&gt; pour un &lt;a class=&quot;pagelink&quot; href=&quot;Roublard-Unchained.html&quot; title=&quot;Le roublard unchained&quot;&gt;roublard unchained&lt;/a&gt;).&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Talents de ma&#238;tre roublard&lt;a class=&quot;headeranchor&quot; id=&quot;Talents_de_ma&#238;tre_roublard_5&quot; href=&quot;#Talents_de_ma&#238;tre_roublard_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Ces talents de ma&#238;tre roublard viennent compl&#233;ter l&#39;arch&#233;type de voleur fant&#244;me : &lt;a class=&quot;pagelink&quot; href=&quot;Talents.html#COLPORTEURDERUMEURS&quot; title=&quot;Les talents de roublard&quot;&gt;colporteur de rumeurs&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Talents.html#DON&quot; title=&quot;Les talents de roublard&quot;&gt;don&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Talents.html#ESRPTICACHE&quot; title=&quot;Les talents de roublard&quot;&gt;esprit cach&#233;&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Talents.html#MAITRISECOMPETENCES&quot; title=&quot;Les talents de roublard&quot;&gt;ma&#238;trise des comp&#233;tences&lt;/a&gt; (ainsi que &lt;a class=&quot;pagelink&quot; href=&quot;Talents-Unchained.html#MULTIPLESSPECIALITES&quot; title=&quot;Les talents du roublard unchained&quot;&gt;multiples sp&#233;cialit&#233;s&lt;/a&gt; pour un &lt;a class=&quot;pagelink&quot; href=&quot;Roublard-Unchained.html&quot; title=&quot;Le roublard unchained&quot;&gt;roublard unchained&lt;/a&gt;).
